    cs2_ecook_points: "<li>Glaskeramik-Oberfl\u00e4chen bester Qualit\u00e4t, f\u00fcr schnelle, m\u00fchelose Reinigung.</li><li>Robuste Strahlungsvarianten oder die beste Induktionstechnik.</li><li>Exklusive, patentierte Kochsysteme.</li><li>Konstruktion in Marinequalit\u00e4t, f\u00fcr das Leben an Bord.</li><li>Auf Wunsch des Eigners individualisierbar.</li>",
    cs2_egrill_tag: "Die Kollektion \u00b7 Elektrogrills",
    cs2_egrill_head: "Tausendfach verbaut<br><em>auf den Yachten der Welt</em>",
